-- Execute together in one transaction / D1 batch before serving substring searches.
CREATE VIRTUAL TABLE IF NOT EXISTS placeSearchTrigramUpgrade USING fts5(
    scopeId UNINDEXED, placeId UNINDEXED, locale UNINDEXED, nameText, brandText, taxonomyText, addressText, divisionText, streetText, tokenize='trigram'
  );

INSERT INTO placeSearchTrigramUpgrade (rowid, scopeId, placeId, locale, nameText, brandText, taxonomyText, addressText, divisionText, streetText) SELECT rowid, scopeId, placeId, locale, CASE WHEN instr(nameText, char(31)) > 0 THEN nameText ELSE TRIM(COALESCE(nameText, '')) || char(31) || TRIM(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(nameText), '!', ''), '"', ''), '#', ''), '$', ''), '%', ''), '&', ''), '''', ''), '(', ''), ')', ''), '*', ''), '+', ''), ',', ''), '-', ''), '.', ''), '/', ''), ':', ''), ';', ''), '<', ''), '=', ''), '>', ''), '?', ''), '@', ''), '[', ''), '\', ''), ']', ''), '^', ''), '_', ''), '`', ''), '{', ''), '|', ''), '}', ''), '~', ''), '·', ''), '…', ''), '“', ''), '”', ''), '‘', ''), '’', ''), '「', ''), '」', ''), '『', ''), '』', ''), '（', ''), '）', ''), '［', ''), '］', ''), '｛', ''), '｝', ''), '！', ''), '？', ''), '、', ''), '。', ''), '，', ''), '：', ''), '；', ''), '＇', ''), '＂', ''), '～', ''), '＿', ''), '－', ''), '＋', ''), '＝', ''), '＠', ''), '＃', ''), '＆', ''), '％', ''), '＊', ''), '／', ''), '＼', ''), '｜', '')) END, CASE WHEN instr(brandText, char(31)) > 0 THEN brandText ELSE TRIM(COALESCE(brandText, '')) || char(31) || TRIM(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(brandText), '!', ''), '"', ''), '#', ''), '$', ''), '%', ''), '&', ''), '''', ''), '(', ''), ')', ''), '*', ''), '+', ''), ',', ''), '-', ''), '.', ''), '/', ''), ':', ''), ';', ''), '<', ''), '=', ''), '>', ''), '?', ''), '@', ''), '[', ''), '\', ''), ']', ''), '^', ''), '_', ''), '`', ''), '{', ''), '|', ''), '}', ''), '~', ''), '·', ''), '…', ''), '“', ''), '”', ''), '‘', ''), '’', ''), '「', ''), '」', ''), '『', ''), '』', ''), '（', ''), '）', ''), '［', ''), '］', ''), '｛', ''), '｝', ''), '！', ''), '？', ''), '、', ''), '。', ''), '，', ''), '：', ''), '；', ''), '＇', ''), '＂', ''), '～', ''), '＿', ''), '－', ''), '＋', ''), '＝', ''), '＠', ''), '＃', ''), '＆', ''), '％', ''), '＊', ''), '／', ''), '＼', ''), '｜', '')) END, taxonomyText, addressText, divisionText, streetText FROM placeSearchFts;

